from html import escape

PROJECT = {'slug':'lions-mma','name':'Lions MMA','sector':'Sport / Club management platform','tags':['Product design','UI / UX','Design system'],'image':'lions/cover.webp','color':'#fe6700','short':'One club community. Every side connected.','context':'A connected product design for members, families, coaches and multi-location club teams.','approach':'Connect the journey from a first class to everyday club operations.','url':'https://www.figma.com/design/yGubuyAati32szKexnpFZZ/Lions-MMA--Club-Management-App?node-id=36-233'}

def figure(name,title,copy,phone=False):
    return f'<figure class="lions-figure {"lions-phone" if phone else ""}"><a href="/assets/lions/{name}.webp" target="_blank" rel="noopener" aria-label="Open {escape(title)} design at full size"><img src="/assets/lions/{name}.webp" loading="lazy" alt="{escape(title+": "+copy)}"></a><figcaption><strong>{title}</strong><p>{copy}</p></figcaption></figure>'

def content():
    member=[('onboarding','A family, not four separate accounts','A five-step registration journey connects children, health details, consent and a plan for each member.'),('home','The next class comes first','A parent sees tonight’s session, the right child’s pass and unfinished tasks without digging through menus.'),('booking','Find a class that fits','Club, discipline and eligibility sit alongside availability, booking and waiting-list states.'),('pass','From booking to the front desk','A child-specific QR pass bridges the member app and the reception check-in workflow.'),('progress','Make progress visible','Parents can follow attendance, belt progress, coach feedback and the next grading milestone.'),('payments','Keep membership understandable','Plans, receipts, payment issues and change requests have a clear place in the account.')]
    staff=[('manager','01 / Club manager','A daily overview turns class capacity, trials, overdue tasks and coach cover into a practical action list.'),('reception','02 / Reception','Search and QR check-in bring member status, walk-ins and incomplete registration into the same front-desk view.'),('coach','03 / Coach on the mats','A tablet register prioritises attendance and relevant safety information, designed around use during a session.'),('reports','04 / Head office','Cross-club reporting brings membership, income, trials, retention and class use into one overview.'),('permissions','05 / Access by responsibility','A permissions matrix separates head office, club managers, coaches and reception, including sensitive member information.')]
    return '''<article class="lions-case"><section class="section lions-intro"><a class="text-link" href="/work/">All work</a><p class="eyebrow">Product design / UI &amp; UX / Figma prototype</p><h1>Lions MMA.</h1><div class="lions-lead"><h2>One club community.<br>Every side connected.</h2><p>A family booking their next class. A coach taking the register. A manager keeping several clubs moving. One connected design, shaped around the different things each person needs to do.</p></div><div class="lions-facts"><div><span>Scope</span><p>Member app · Staff workspace · Public website</p></div><div><span>Design work</span><p>User journeys · Interfaces · Reusable components</p></div><div><span>Project stage</span><p>Design &amp; prototype</p></div></div></section><div class="lions-cover"><img src="/assets/lions/cover.webp" alt="Lions MMA member app screens alongside its club management dashboard" width="1600" height="1100"></div><section class="section"><div class="lions-chapter"><p class="eyebrow">01 / The product challenge</p><h2>More than<br>a booking app.</h2><div><p>The hard part is connecting the people around a class. A parent manages several children, reception needs to know who can train, a coach needs the right register, and head office needs a view across clubs.</p><p>The design gives each role a focused workspace while keeping memberships, bookings, attendance and progress part of the same journey.</p></div></div><div class="lions-scale"><div><strong>16</strong><span>main member app screens</span></div><div><strong>11</strong><span>staff and coach screens</span></div><div><strong>12</strong><span>desktop website page states, with mobile companions</span></div></div><p class="lions-note">Design scope counted from the Figma file; overlays and the mobile menu are additional. Example names, figures and photography belong to the prototype.</p></section><section class="section lions-member" id="member-experience"><div class="lions-section-title"><p class="eyebrow">02 / Members &amp; families</p><h2>Less admin.<br>More time on the mats.</h2><p>The app follows the member’s routine: join, choose a class, check in, track progress and manage the account. A parent can move between children without starting again.</p></div><div class="lions-phones">'''+''.join(figure(n,t,c,True) for n,t,c in member)+'''</div></section><section class="section" id="staff-experience"><div class="lions-section-title"><p class="eyebrow">03 / Behind the scenes</p><h2>The same club.<br>A different view.</h2><p>Staff screens are organised around responsibility. Daily operations, the front desk, coaching and head-office reporting each have their own priorities.</p></div><div class="lions-desktops">'''+''.join(figure(n,t,c) for n,t,c in staff)+'''</div></section><section class="section"><div class="lions-chapter"><p class="eyebrow">04 / Connected workflows</p><h2>The details<br>between screens.</h2><div><p>Registration includes duplicate-member recognition, separate consent choices and unfinished-form reminders. Booking considers membership eligibility, capacity and waiting lists.</p><p>The wider staff design also covers sign-ups, recurring timetables, coach cover, payment exceptions, targeted messages and expiring staff qualifications. These are designed workflows; payment, messaging and access enforcement still require implementation.</p></div></div><div class="lions-workflow"><div><span>Join</span><p>Family profiles, health details, consent and membership selection.</p></div><div><span>Train</span><p>Eligible classes, bookings, QR passes and attendance registers.</p></div><div><span>Keep connected</span><p>Progress, grading, updates, payments and staff follow-up.</p></div></div></section><section class="section lions-website"><div class="lions-section-title"><p class="eyebrow">05 / Before the first class</p><h2>A public front door<br>to the whole experience.</h2><p>The responsive website introduces classes and clubs, answers first-visit questions and leads into free-trial booking. Community pages extend the story to Punjab projects, volunteering and donations.</p></div><div class="lions-web-preview"><a href="/assets/lions/website.webp" target="_blank" rel="noopener"><img src="/assets/lions/website.webp" loading="lazy" alt="Full Lions MMA desktop homepage design, from class discovery to membership and community content"></a></div><p class="lions-note">Scrollable homepage design. Open the image to inspect the full page. Photography is placeholder imagery in the Figma design.</p></section><section class="section"><div class="lions-chapter"><p class="eyebrow">06 / Design language</p><h2>Warm for families.<br>Clear for staff.</h2><div><p>The app pairs warm neutral surfaces with Lions orange for primary actions, rounded cards and plain-English labels. Denser desktop layouts keep operational information visible without giving every role the same screen.</p><p>A shared design system supports buttons, inputs, navigation, feedback and status patterns. The public website takes a quieter monochrome direction, giving imagery and the orange identity more room.</p></div></div><div class="lions-status"><p class="eyebrow">What this case study shows</p><h3>A designed product system.</h3><p>These are Figma screens and prototype journeys. Production development, integrations, data migration, accessibility testing and launch validation are separate delivery stages. No live usage or business results are claimed.</p><a class="pill" href="https://www.figma.com/design/yGubuyAati32szKexnpFZZ/Lions-MMA--Club-Management-App?node-id=36-233" target="_blank" rel="noopener">Explore the Figma design</a></div></section><section class="section next-project"><p class="eyebrow">Explore another digital product</p><a href="/work/joinery-studio/">Joinery Studio.</a></section></article>'''
